  'legal.updated': 'Last updated 17 September 2026.',
  'legal.privacy.title': 'Privacy',
  'legal.privacy.intro': 'Nomi is the assistant a business uses to answer the people who write to it on Instagram, Facebook Messenger, WhatsApp and e-mail. This page says what is kept when you write to a business that uses it, why, and how to have it removed.',
  'legal.privacy.kept.title': 'What is kept',
  'legal.privacy.kept.body': 'When you send a message to a business that uses Nomi, we keep the message, any picture or file you attach, the name shown on your account, the identifier the platform gives us for your account, and the time it arrived. If the business writes to you by e-mail with your consent, your e-mail address and the messages exchanged are kept in the same way.',
  'legal.privacy.why.title': 'Why',
  'legal.privacy.why.body': 'So the business can read your message and answer it. Replies are drafted by Nomi and, depending on how the business set it up, sent after a person there approves them. Your messages are not used to advertise to you and are not sold.',
  'legal.privacy.who.title': 'Who sees it',
  'legal.privacy.who.body': 'The business you wrote to, and the services it takes to carry and answer your message:',
  'legal.privacy.who.meta': 'Meta, which carries Instagram, Messenger and WhatsApp messages between you and the business.',
  'legal.privacy.who.anthropic': 'Anthropic, whose language service drafts replies from the text of the conversation.',
  'legal.privacy.who.hosting': 'Railway, the hosting provider the service runs on.',
  'legal.privacy.who.mail': 'If the business connected a mailbox, the mail provider it uses (Google or Microsoft) carries the e-mail.',
  'legal.privacy.who.nobody': 'Nobody else.',
  'legal.privacy.howLong.title': 'How long',
  'legal.privacy.howLong.body': 'For as long as the business uses Nomi, so it can see what was agreed with you — a price, an order, a sample. Ask, and it is removed sooner.',
  'legal.privacy.choices.title': 'Your choices',
  'legal.privacy.choices.body': 'You can ask for a copy of what is kept about you, or ask for it to be removed. Every e-mail the business sends carries a link that stops further mail.',
  'legal.privacy.deletionLink': 'How to have your data removed',
  'legal.contact.title': 'How to reach us',
  'legal.contact.write': 'Write to',
  'legal.contact.same': 'Or send the business a message saying so, from the account you used.',
  'legal.deletion.title': 'Delete your data',
  'legal.deletion.intro': 'You can have everything a business kept about you through Nomi removed.',
  'legal.deletion.step1': 'Ask. From the Instagram, Facebook or WhatsApp account you wrote from, send the business a message saying you want your data deleted — or write to the address below from the e-mail address you used.',
  'legal.deletion.step2': 'Within 30 days, your messages, attachments, name and account identifiers are removed from Nomi, and you receive a confirmation on the same channel.',
  'legal.deletion.step3': 'What stays: records the business must keep by law, such as an invoice for an order you placed; and the copies Meta itself holds, which you manage in your own Instagram or Facebook settings.',
  'legal.deletion.revoked': 'Removing Nomi from your Meta account settings stops new messages from reaching it. It does not remove what was already kept — ask for that here.',
  'legal.privacyLink': 'Privacy',
  'legal.termsLink': 'Terms of service',
  'legal.terms.title': 'Terms of service',
  'legal.terms.intro': 'These terms are between a business that uses Nomi and the operator of Nomi, reachable at nomidoes.com. Using Nomi means agreeing to them. People who write to a business through Nomi are covered by the privacy page, not by these terms.',
  'legal.terms.service.title': 'What Nomi does',
  'legal.terms.service.body': 'Nomi answers the people who write to your business on the channels you connect — Instagram, Facebook Messenger, WhatsApp and e-mail — drafts replies from your own catalogue and prices, and keeps the record of what was said. By default every reply waits for a person at your business to approve it; what it may send on its own is your decision, and you can take it back at any time.',
  'legal.terms.yours.title': 'What you undertake',
  'legal.terms.yours.you1': 'You use the channels you connect within their own rules, and you write first only to people who agreed to hear from you.',
  'legal.terms.yours.you2': 'The catalogue, prices and facts you give Nomi are yours and are true; it says nothing about your business that you did not put in.',
  'legal.terms.yours.you3': 'Orders, payments and shipments are confirmed by you. Nomi never concludes a contract in your name.',
  'legal.terms.ours.title': 'What Nomi undertakes',
  'legal.terms.ours.we1': 'A price it quotes comes from your own price list and is never below the floor you set.',
  'legal.terms.ours.we2': 'Confirming an order always takes a person at your business.',
  'legal.terms.ours.we3': 'When it cannot answer, it says so and holds the message for you; nothing is dropped in silence.',
  'legal.terms.ours.we4': 'Everything it sends is on the record, so you can see what was said and by whom.',
  'legal.terms.fees.title': 'Fees and leaving',
  'legal.terms.fees.body': 'Fees are as agreed with you in writing. You can stop at any time; after that your records can be exported in full, and are removed on request as the privacy page describes.',
  'legal.terms.liability.title': 'Responsibility',
  'legal.terms.liability.body': 'You are responsible for the business consequences of what you approved. For a fault in Nomi itself, the operator repairs it and tells you plainly what happened; the operator\'s total liability for any month is capped at what you paid for that month.',
  'legal.terms.changes.title': 'Changes',
  'legal.terms.changes.body': 'When these terms change, the date below changes with them, and you are told before a change that narrows what you were promised takes effect.',
